  lines.push("");
  lines.push("# Draft proposal report");
  lines.push("");
  lines.push(
    `nav seeds: ${report.stats.navSeeds} \xB7 domains: ${report.stats.domains} \xB7 features: ${report.stats.features} \xB7 orphan share: ${report.stats.orphanShare}`
  );
